c083.try_sql:
-- From a DATE: YEAR/MONTH/DAY work, HOUR only after CAST to TIMESTAMP
SELECT EXTRACT(DAY FROM DATE '2024-03-31') AS d,
       EXTRACT(HOUR FROM CAST(TO_DATE('2024-03-31 14:45', 'YYYY-MM-DD HH24:MI') AS TIMESTAMP)) AS h
FROM   dual;
SELECT EXTRACT(HOUR FROM SYSDATE) FROM dual;

c085.try_sql:
-- ADD_MONTHS gives the end of February, + INTERVAL '1' MONTH raises an error
SELECT ADD_MONTHS(DATE '2024-01-31', 1) AS am FROM dual;
SELECT DATE '2024-01-31' + INTERVAL '1' MONTH FROM dual;

c711.try_sql:
-- The right units work, 'DAY' in NUMTOYMINTERVAL raises an error
SELECT NUMTOYMINTERVAL(18, 'MONTH') AS ym, NUMTODSINTERVAL(36, 'HOUR') AS ds FROM dual;
SELECT NUMTOYMINTERVAL(2, 'DAY') FROM dual;

c713.try_sql:
-- DAY(3) allows 3 digits, the default DAY(2) does not
SELECT INTERVAL '123' DAY(3) AS ok FROM dual;
SELECT INTERVAL '123' DAY FROM dual;

c1729.try_sql:
-- From a TIMESTAMP, seconds with a fraction; from a DATE, SECOND raises an error
SELECT EXTRACT(SECOND FROM TIMESTAMP '2024-03-31 10:15:30.5') AS s FROM dual;
SELECT EXTRACT(SECOND FROM SYSDATE) FROM dual;

c1730.try_sql:
-- TIMEZONE_HOUR only from a value with a time zone; LOCALTIMESTAMP has none
SELECT EXTRACT(TIMEZONE_HOUR FROM TIMESTAMP '2024-07-01 12:00:00 Europe/Warsaw') AS warsaw,
       EXTRACT(TIMEZONE_HOUR FROM SYSTIMESTAMP) AS sys
FROM   dual;
SELECT EXTRACT(TIMEZONE_HOUR FROM LOCALTIMESTAMP) FROM dual;

c1731.try_sql:
-- The 'days hh:mi:ss' and ISO formats work; '36:00:00' without days does not
SELECT TO_DSINTERVAL('1 12:00:00') AS a, TO_DSINTERVAL('PT36H') AS b FROM dual;
SELECT TO_DSINTERVAL('36:00:00') FROM dual;

c1734.try_sql:
-- Two safe ways, and then an INTERVAL subtraction that fails
SELECT ADD_MONTHS(DATE '2024-03-31', -1) AS a, TRUNC(DATE '2024-03-31', 'MM') - 1 AS b FROM dual;
SELECT DATE '2024-03-31' - INTERVAL '1' MONTH FROM dual;

c1735.try_sql:
-- duration is INTERVAL DAY(2) TO SECOND(0): 15.75 s rounds to 16 s, 120 days is an error
UPDATE events e SET e.duration = INTERVAL '0 00:00:15.75' DAY TO SECOND WHERE e.event_id = 4;
SELECT e.duration FROM events e WHERE e.event_id = 4;
UPDATE events e SET e.duration = INTERVAL '120' DAY(3) WHERE e.event_id = 4;

c1736.try_sql:
-- Comparing with an INTERVAL literal works, with the number 1 it does not
SELECT e.event_id, e.duration FROM events e WHERE e.duration > INTERVAL '1' HOUR;
SELECT e.event_id FROM events e WHERE e.duration > 1;
